(()=>{
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)], D=window.PORTAL_DATA;
const KEY='hjs_ils_year9_computing_v1'; let state=load(), currentPage='dashboard', lang='en', noteId='devices', exam=null, timerHandle=null, practiceMode=false, sourceAttempt=null;
function load(){try{return JSON.parse(localStorage.getItem(KEY))||{user:null,results:[],completed:[],answers:{},notesSeen:[],settings:{}}}catch{return {user:null,results:[],completed:[],answers:{},notesSeen:[],settings:{}}}}
function save(){localStorage.setItem(KEY,JSON.stringify(state))}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function pageTitle(p){return ({marking:'Marking Guide',dashboard:'Dashboard',overview:'Course Overview',notes:'Study Notes',marking:'Marking Guide',materials:'Learning Materials',papers:'Past Papers',practice:'Practice Exams',practical:'ICT Practical Skills',results:'My Results',progress:'Progress Report',profile:'Student Profile',teacher:'Teacher Dashboard',settings:'Settings'})[p]||p}
function login(name){state.user={name,role:'student'};save();$('#loginScreen').classList.add('hidden');$('#app').classList.remove('hidden');$('#topName').textContent=name;$('#avatar').textContent=name.charAt(0).toUpperCase();render()}
$('#loginForm').addEventListener('submit',e=>{e.preventDefault();let n=$('#studentName').value.trim(),p=$('#password').value;if(!n)return;if(p!=='HJSPearson92026'){$('#loginError').textContent='Incorrect password. Please try again.';return}$('#loginError').textContent='';login(n)});
$('#logoutBtn').onclick=()=>{if(confirm('Sign out of the learning portal?')){state.user=null;save();location.reload()}};
$('#nav').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});$('#content').addEventListener('click',e=>{let b=e.target.closest('[data-page]');if(b)go(b.dataset.page)});
function go(p){currentPage=p;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===p));$('#crumb').textContent=pageTitle(p);$('#sidebar').classList.remove('open');render()}
$('#menuBtn').onclick=()=>$('#sidebar').classList.add('open');$('#closeSide').onclick=()=>$('#sidebar').classList.remove('open');function applyStaticLanguage(){document.querySelectorAll('[data-en][data-my]').forEach(el=>{el.textContent=lang==='my'?el.dataset.my:el.dataset.en});document.querySelectorAll('[data-en-placeholder][data-my-placeholder]').forEach(el=>el.placeholder=lang==='my'?el.dataset.myPlaceholder:el.dataset.enPlaceholder);$('#langBtn').textContent=lang==='en'?'မြန်မာ':'English'}
function toggleLanguage(){lang=lang==='en'?'my':'en';applyStaticLanguage();render()}
$('#langBtn').onclick=toggleLanguage;$('#loginLangBtn')?.addEventListener('click',toggleLanguage);
function heading(kicker,title,sub,action=''){return `<div class="page-heading"><div><div class="eyebrow2">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function panelHead(t,s=''){return `<div class="panel-head"><h3>${t}</h3><small>${s}</small></div>`}
function dashboard(){let completed=state.completed.length,avg=state.results.length?Math.round(state.results.reduce((a,r)=>a+r.percent,0)/state.results.length):0,last=state.results[0];return `${heading('YOUR LEARNING SPACE',`Good ${new Date().getHours()<12?'morning':new Date().getHours()<18?'afternoon':'evening'}, ${esc(state.user.name)} 👋`,'Ready to make progress? Your next achievement starts with one lesson.')}<section class="panel welcome"><div class="eyebrow2" style="color:#e1c77f">YOUR COURSE • 2026</div><h2>Build your Computing confidence.</h2><p>Learn the concepts, practise the skills and prepare for your Year 9 Computing assessment.</p><button class="btn" data-page="notes">Continue learning →</button></section><div class="grid stats-grid"><div class="stat-card"><div class="stat-top">Lessons completed <span class="stat-icon">▧</span></div><div class="stat-value">${completed}</div><div class="stat-foot">Across your study topics</div></div><div class="stat-card"><div class="stat-top">Average exam score <span class="stat-icon">◔</span></div><div class="stat-value">${avg}%</div><div class="stat-foot">Based on completed attempts</div></div><div class="stat-card"><div class="stat-top">Exams completed <span class="stat-icon">✎</span></div><div class="stat-value">${state.results.length}</div><div class="stat-foot">Practice history saved here</div></div><div class="stat-card"><div class="stat-top">Study topics <span class="stat-icon">✦</span></div><div class="stat-value">${D.notes.length}</div><div class="stat-foot">Detailed bilingual notes</div></div></div><div class="grid dashboard-grid"><div><section class="panel">${panelHead('Your course progress','Personal learning tracker')}<div class="course-progress"><div class="ring"><b>${Math.round(completed/D.notes.length*100)}%</b></div><div style="flex:1"><b style="font-size:12px">Year 9 Computing</b><p>${completed} of ${D.notes.length} study topics marked complete. Open a topic and mark it complete when you finish.</p><div class="progress-line"><span style="width:${completed/D.notes.length*100}%"></span></div></div></div></section><section class="panel">${panelHead('Continue learning','Recommended next step')}<div class="list-row"><div class="list-icon">▧</div><div><b>Digital Safety, Security & Wellbeing</b><small>Passwords • cyberbullying • copyright</small></div><span class="right">20 min</span></div><div class="list-row"><div class="list-icon">⌘</div><div><b>Algorithms & Flowcharts</b><small>Sequence • selection • data types</small></div><span class="right">25 min</span></div><button class="btn outline" data-page="notes">Browse all study notes</button></section></div><div><section class="panel">${panelHead('Recent examination','Latest attempt')} ${last?`<div class="result-score"><div class="score-big">${last.percent}%</div><div><b>${esc(last.title)}</b><p style="font-size:10px;color:var(--muted)">${new Date(last.date).toLocaleDateString()} • ${last.score}/${last.max} marks</p><span class="pill ${last.percent>=50?'green':'gold'}">${last.percent>=50?'Pass':'Keep practising'}</span></div></div>`:`<div class="empty">No exam attempts yet.<br>Open a Year 9 past paper or study a topic to get started.</div>`}<button class="btn outline" style="margin-top:14px" data-page="results">View all results</button></section><section class="panel">${panelHead('Quick access','Jump right in')}<div class="list-row"><div class="list-icon">✎</div><div><b>Year 9 Past Papers</b><small>Question papers • mark schemes • examiner reports</small></div><button class="text-link" data-page="papers">Browse →</button></div><div class="list-row"><div class="list-icon">▣</div><div><b>Learning materials</b><small>Original PDFs and mark schemes</small></div><button class="text-link" data-page="materials">Open →</button></div></section></div></div>`}
function overview(){return `${heading('COURSE GUIDE','Course Overview','Your route through Pearson Edexcel International Award in Lower Secondary Computing (LCP11/01).')}<section class="panel"><div class="eyebrow2">COURSE PURPOSE</div><h2 style="font:700 24px 'Playfair Display';color:var(--navy)">Understand technology. Apply your knowledge. Think logically.</h2><p class="muted">This learning portal brings together bilingual study notes, original source papers, interactive practice and practical ICT tasks. The supplied examination documents identify the qualification as Pearson Edexcel International Award in Lower Secondary Computing, Year 9, Paper LCP11/01.</p></section><div class="grid three-col">${D.notes.map((n,i)=>`<article class="lesson-card"><div class="card-kicker">UNIT 0${i+1} • ${n.tag}</div><h3>${n.title}</h3><p>${n.intro}</p><div class="card-meta"><span>✦ Bilingual notes</span><span>• Key terms</span></div><button class="btn outline" data-open-note="${n.id}">Open topic →</button></article>`).join('')}</div><section class="panel" style="margin-top:17px">${panelHead('Suggested study routine','A simple weekly approach')}<div class="grid three-col"><div><b>01 · Learn</b><p class="muted">Read one topic in English or Myanmar and review the key terms.</p></div><div><b>02 · Apply</b><p class="muted">Complete a practical task and explain what you did.</p></div><div><b>03 · Check</b><p class="muted">Attempt exam questions, review feedback and revisit weak areas.</p></div></div></section>`}
function noteVisual(id){
const boards={
systems:`<div class="diagram-flow"><div class="diagram-node io">INPUT DEVICES<br><small>Keyboard • Mouse • Webcam</small></div><b class="diagram-arrow">↓</b><div class="diagram-node process">CPU + MAIN MEMORY<br><small>Fetch • Decode • Execute</small></div><b class="diagram-arrow">↓</b><div class="diagram-node io">OUTPUT<br><small>Monitor • Speaker • Printer</small></div><div class="diagram-side">↔ <b>SECONDARY STORAGE</b><small>HDD • SSD • USB</small></div></div><div class="visual-caption">A computer system accepts data, processes it, produces output and stores information for later use.</div>`,
binary:`<div class="place-value"><div class="pv-head">8-bit place values</div>${[128,64,32,16,8,4,2,1].map((v,i)=>`<div class="pv-cell"><b>${v}</b><span>${"11001101"[i]}</span></div>`).join('')}</div><div class="binary-work"><b>Worked example: 205</b><div>128 + 64 + 8 + 4 + 1 = <strong>205</strong></div><div class="binary-answer">1100 1101₂ = 205₁₀</div></div><div class="visual-caption">Read each column from left to right. Add only the place values whose bit is 1.</div>`,
networks:`<div class="network-map"><div class="network-center">SWITCH</div><div class="network-device d1">PC 1</div><div class="network-device d2">PC 2</div><div class="network-device d3">PRINTER</div><div class="network-device d4">SERVER</div><div class="network-note">LAN: connected devices share data and resources</div></div><div class="network-types"><div><b>PAN</b><small>Personal • around 10 m in the paper's context</small></div><div><b>LAN</b><small>Local site • home / school / office</small></div><div><b>WAN</b><small>Wide area • connects distant networks</small></div></div>`,
internet:`<div class="packet-diagram"><div class="packet-head"><b>PACKET HEADER</b><span>Source address • Destination address • Sequence / control data</span></div><div class="packet-payload"><b>PAYLOAD</b><span>Part of the original message / file</span></div></div><div class="web-path"><div>USER DEVICE<br><small>Browser</small></div><b>→ REQUEST →</b><div>INTERNET<br><small>Packets travel</small></div><b>→ REQUEST →</b><div>WEB SERVER<br><small>Website files</small></div></div><div class="visual-caption">A URL identifies a Web resource. Packets carry payload data and header control information.</div>`,
safety:`<div class="safety-wheel"><div class="safety-core">DIGITAL<br>SAFETY</div><div class="safety-orbit"><span>PRIVACY<br><small>Limit audience</small></span><span>SECURITY<br><small>Strong passwords</small></span><span>RESPECT<br><small>Copyright & credit</small></span><span>WELLBEING<br><small>Block & report</small></span></div></div><div class="safety-alert"><b>STOP • CHECK • THINK</b><span>Unknown link or USB? Verify the source before opening or connecting.</span></div>`,
programming:`<div class="code-panel"><div class="code-title">PYTHON EXAMPLE</div><pre>name = "Aye"       # string\nscore = 75        # integer\npassed = score >= 50  # Boolean\nremainder = 5 % 2     # 1\nwhole = 5 // 2        # 2\nprint(name, passed)</pre></div><div class="operator-grid"><span><b>=</b> Assign</span><span><b>==</b> Equal</span><span><b>!=</b> Not equal</span><span><b>&lt;=</b> Less/equal</span><span><b>//</b> Integer divide</span><span><b>%</b> Remainder</span></div>`,
algorithms:`<div class="flowchart"><div class="fc-oval">START</div><div class="fc-arrow">↓</div><div class="fc-io">INPUT age</div><div class="fc-arrow">↓</div><div class="fc-diamond"><span>age ≥ 18?</span></div><div class="fc-branches"><div><b>YES</b><div class="fc-process">Display "Adult"</div></div><div><b>NO</b><div class="fc-process">Display "Under 18"</div></div></div><div class="fc-arrow">↓</div><div class="fc-oval">END</div></div><div class="shape-legend"><span><i class="oval-key"></i> Oval = Start / End</span><span><i class="io-key"></i> Parallelogram = Input / Output</span><span><i class="rect-key"></i> Rectangle = Process</span><span><i class="diamond-key"></i> Diamond = Decision</span></div>`,
models:`<div class="array-board"><div class="array-title">PYTHON LIST: items = [4, 7, 2]</div><div class="array-index"><span>Index</span><b>0</b><b>1</b><b>2</b></div><div class="array-values"><span>Value</span><strong>4</strong><strong>7</strong><strong>2</strong></div><div class="array-foot">len(items) = 3 • Last valid index = len(items) − 1 = 2</div></div><div class="sort-steps"><div><b>Before</b><span>5 | 2 | 4</span></div><div><b>Compare</b><span>5 &gt; 2 → swap</span></div><div><b>After pass</b><span>2 | 4 | 5</span></div></div>`
};
const descriptions={
systems:"System diagram: input, processing, output and storage are connected parts of one computer system.",
binary:"Binary place-value chart and a worked conversion from denary 205 to 8-bit binary.",
networks:"Network diagram: a switch connects computers, a printer and a server inside a LAN.",
internet:"Packet structure and the request path between a browser, the Internet and a web server.",
safety:"Digital responsibility map covering privacy, security, respect and wellbeing.",
programming:"Python code sample with variables, Boolean comparison and arithmetic operators.",
algorithms:"Flowchart example showing input, a decision and two output paths.",
models:"List indexing and a simple comparison-and-swap sequence."
};
return `<section class="visual-study-panel"><div class="visual-study-head"><div><span class="card-kicker">VISUAL LEARNING • DIAGRAMS • SHAPES</span><h3>${lang==='en'?'Visual explanation':'ပုံဖြင့်ရှင်းလင်းချက်'}</h3><p>${lang==='en'?descriptions[id]||'Study the diagram and explain each component.':'ပုံထဲရှိ အစိတ်အပိုင်းတစ်ခုချင်းစီ၏ အမည်၊ လုပ်ဆောင်ချက်နှင့် ဆက်စပ်ပုံကို လေ့လာပါ။'}</p></div><span class="visual-study-badge">YEAR 9 GUIDE</span></div>${boards[id]||''}<div class="visual-exam-tip"><b>${lang==='en'?'How to describe a diagram':'Diagram ရှင်းပြနည်း'}:</b> ${lang==='en'?'Name the symbol or component, state its function, then explain the direction or relationship shown by the arrows.':'ပုံသဏ္ဌာန်/အစိတ်အပိုင်းအမည်ကိုရေးပါ။ ၎င်း၏လုပ်ဆောင်ချက်ကိုဖော်ပြပြီး မြှားများကပြသော ဦးတည်ချက် သို့မဟုတ် ဆက်စပ်မှုကို ရှင်းပြပါ။'}</div></section>`;
}
function notes(){let n=D.notes.find(x=>x.id===noteId)||D.notes[0],e=(window.STUDY_ENHANCEMENTS||{})[n.id]||{};return `${heading('KNOWLEDGE LIBRARY','Year 9 Study Notes','Expanded revision notes • bilingual explanations • examples • memory checks • exam practice.')}<div class="notes-layout"><aside class="panel topic-list"><div class="eyebrow2" style="padding:5px 10px 12px">TOPIC INDEX</div>${D.notes.map((x,i)=>`<button class="${x.id===n.id?'active':''}" data-note="${x.id}">0${i+1} · ${lang==='en'?x.title:x.my}</button>`).join('')}<button class="marking-shortcut" data-page="marking">✦ ${lang==='en'?'How marks are awarded':'အမှတ်ပေးနည်းလမ်း'}</button></aside><article class="panel note-body note-reader"><div class="note-cover"><div class="card-kicker">${n.tag} • YEAR 9 • STUDY CHAPTER</div><h2>${lang==='en'?n.title:n.my}</h2><p>${lang==='en'?n.intro:n.introMy}</p><div class="note-cover-meta"><span>READ</span><span>UNDERSTAND</span><span>RECALL</span><span>APPLY</span></div></div>${noteVisual(n.id)}<section class="memory-banner"><b>${lang==='en'?'CHAPTER IN ONE SENTENCE':'အခန်းတစ်ခုလုံးကို တစ်ကြောင်းတည်းဖြင့်'}</b><p>${lang==='en'?e.summary||n.intro:(e.summaryMy||n.introMy)}</p></section>${n.sections.map(([t,en,my],i)=>`<section class="lesson-section"><div class="lesson-number">0${i+1}</div><div class="lesson-copy"><h3>${t}</h3><p>${lang==='en'?en:my}</p>${i===0?`<div class="exam-tip-inline"><b>${lang==='en'?'Remember':'မှတ်သားရန်'}:</b> ${lang==='en'?'Learn the exact technical term and be able to explain it in your own words.':'နည်းပညာဝေါဟာရကို အဓိပ္ပာယ်နှင့်တကွ မှတ်သားပြီး ကိုယ့်စကားဖြင့် ပြန်ရှင်းပြနိုင်အောင် လေ့ကျင့်ပါ။'}</div>`:''}</div></section>`).join('')}${(e.sections||[]).map(([t,en,my],i)=>`<section class="lesson-section extended"><div class="lesson-number">0${i+6}</div><div class="lesson-copy"><h3>${t}</h3><p>${lang==='en'?en:my}</p></div></section>`).join('')}<section class="revision-card"><div class="card-kicker">${lang==='en'?'FAST REVISION':'အမြန်ပြန်လည်လေ့လာရန်'}</div><h3>${lang==='en'?'What you must remember':'မဖြစ်မနေ မှတ်သားရမည့်အချက်များ'}</h3><ul>${(lang==='en'?(e.recall||[]):(e.recallMy||e.recall||[])).map(x=>`<li>${x}</li>`).join('')}</ul></section><section class="mistake-card"><div class="card-kicker">${lang==='en'?'AVOID THESE ERRORS':'သတိထားရမည့် အမှားများ'}</div><h3>${lang==='en'?'Common exam mistakes':'စာမေးပွဲတွင် မကြာခဏမှားတတ်သောအချက်များ'}</h3><ul>${(lang==='en'?(e.mistakes||[]):(e.mistakesMy||e.mistakes||[])).map(x=>`<li>${x}</li>`).join('')}</ul></section><section class="panel term-panel"><h3>${lang==='en'?'Key terminology':'အဓိကဝေါဟာရများ'}</h3><div class="term-grid">${n.terms.map(t=>`<div class="term-card"><b>${t[0]}</b><span>${t[1]}</span><small>${t[2]}</small></div>`).join('')}</div></section><section class="panel self-test"><div class="card-kicker">${lang==='en'?'ACTIVE RECALL':'ကိုယ်တိုင်ပြန်လည်ဖြေဆိုရန်'}</div><h3>${lang==='en'?'Check your understanding':'နားလည်မှုကို စစ်ဆေးပါ'}</h3><p class="muted">${lang==='en'?'Try answering before revealing the suggested answer.':'အဖြေမကြည့်မီ ကိုယ်တိုင်အရင်ဖြေဆိုကြည့်ပါ။'}</p>${(lang==='en'?(e.practice||[]):(e.practiceMy||e.practice||[])).map((q,i)=>`<details class="recall-question"><summary><b>Q${i+1}.</b> ${q[0]}</summary><div class="recall-answer"><b>${lang==='en'?'Suggested answer':'နမူနာအဖြေ'}</b><p>${q[1]}</p></div></details>`).join('')}</section><section class="exam-technique-panel"><h3>${lang==='en'?'Exam writing checklist':'စာမေးပွဲအဖြေရေး Checklist'}</h3><ol><li>${lang==='en'?'Underline the command word and identify exactly what is being asked.':'မေးခွန်း၏ Command Word ကို သတ်မှတ်ပြီး ဘာမေးထားသည်ကို တိတိကျကျ နားလည်ပါ။'}</li><li>${lang==='en'?'Use the correct technical term, not a vague everyday phrase.':'မရှင်းလင်းသော စကားလုံးအစား သက်ဆိုင်ရာ Technical Term ကို သုံးပါ။'}</li><li>${lang==='en'?'For explain questions, connect cause and effect using because, so or therefore.':'Explain မေးခွန်းတွင် ဘာကြောင့်/ဘယ်လိုဖြစ်သည်ကို အကြောင်းရင်းနှင့် အကျိုးဆက် ချိတ်ဆက်ရေးပါ။'}</li><li>${lang==='en'?'Check the number of marks and give enough distinct points.':'ပေးထားသော Marks အရ လိုအပ်သည့် မတူညီသောအချက်အရေအတွက်ကို ရေးပါ။'}</li></ol></section><button class="btn gold-btn" data-complete="${n.id}">${state.completed.includes(n.id)?'✓ Topic completed':'Mark topic as completed'}</button></article></div>`}
function marking(){return `${heading('EXAM SUCCESS TOOLKIT','How Pearson Marking Works','A practical guide based on the General Marking Guidance and question-specific mark schemes in the supplied Year 9 source PDFs.')}<div class="marking-hero"><div><div class="card-kicker">MARK SMARTER • WRITE CLEARER</div><h2>Marks are earned by showing the required knowledge.</h2><p>Do not write long paragraphs automatically. Match the command word, the number of marks and the exact task.</p></div><div class="marking-score-icon">1<span>MARK</span></div></div><div class="marking-grid"><article class="marking-card"><span class="marking-number">01</span><h3>One-mark questions</h3><p>One accurate, relevant fact normally earns one mark when the scheme says “Award one mark for…”. Give a precise term or a single clear point.</p><div class="marking-example"><b>Question:</b> What is a URL?<br><b>Strong answer:</b> The web address used to locate a resource.<br><b>Why:</b> It gives the key definition without unrelated detail.</div></article><article class="marking-card"><span class="marking-number">02</span><h3>Two-mark questions</h3><p>Look for two separate creditworthy points, or a linked explanation if the scheme requires a relationship. Do not repeat the same idea using different words.</p><div class="marking-example"><b>Useful structure:</b><br>Point 1: identify the feature.<br>Point 2: explain its effect or purpose.</div></article><article class="marking-card"><span class="marking-number">03</span><h3>Describe vs explain</h3><p><b>Describe:</b> say what happens or what something is like. <b>Explain:</b> connect the reason to the result. A linked explanation may receive more credit than a bare statement when specified by the scheme.</p><div class="marking-example"><b>Explain pattern:</b> Because [cause], [process] happens, which means [result].</div></article><article class="marking-card"><span class="marking-number">04</span><h3>Multiple-choice questions</h3><p>Select the single best option unless the question explicitly says select more than one. Read every option; eliminate choices that describe a different device, protocol or process.</p><div class="marking-example"><b>Tip:</b> If the scheme says “the only correct answer is B”, the other options do not receive the mark.</div></article><article class="marking-card"><span class="marking-number">05</span><h3>Calculations and conversions</h3><p>Write the method, intermediate steps and unit. For binary, show place values and carries. For data-size or speed questions, keep bits and bytes distinct and follow the conversion stated in the question.</p><div class="marking-example"><b>Example:</b> 45 = 32 + 8 + 4 + 1 = 00101101₂ (8-bit).</div></article><article class="marking-card"><span class="marking-number">06</span><h3>Acceptable alternatives</h3><p>Some schemes list several accepted words or phrases. A correct equivalent term can earn credit where the scheme allows it. However, do not assume every synonym is accepted; check the specific scheme and any “Do not accept” notes.</p><div class="marking-example"><b>Tip:</b> Use the technical vocabulary taught in the notes and avoid vague wording.</div></article></div><section class="panel marking-rules"><div class="card-kicker">GENERAL MARKING GUIDANCE</div><h3>Important principles in the supplied Pearson mark schemes</h3><ul><li><b>Positive marking:</b> credit what the learner has demonstrated, rather than penalising unrelated omissions.</li><li><b>Same standard:</b> the same marking approach should be applied consistently to every candidate.</li><li><b>Use the full range:</b> award all marks deserved; zero is appropriate when no creditworthy response is given.</li><li><b>Maximum marks:</b> if the scheme states “up to” or a maximum, do not exceed that cap even if more points are written.</li><li><b>Alternative answers:</b> accept alternatives only where the scheme permits them or where they clearly meet its stated principle.</li><li><b>Do not credit repeats:</b> two versions of the same point are not automatically two separate marks.</li><li><b>Crossed-out work:</b> crossed-out work can still be marked unless it has been replaced by another answer.</li><li><b>Judgement:</b> where the scheme requires judgement, follow its principles; ambiguous cases should be escalated to a teacher/lead marker.</li></ul></section><section class="panel command-words"><h3>Command words: what should I write?</h3><div class="command-row"><b>State / Name / Identify</b><span>Give the fact, term or item. Keep it direct.</span></div><div class="command-row"><b>Describe</b><span>Give a characteristic or sequence of what happens. Add detail relevant to the scenario.</span></div><div class="command-row"><b>Explain</b><span>Give a reason and link it to an effect using because / therefore / so that.</span></div><div class="command-row"><b>Compare</b><span>Make a direct comparison using both sides, e.g. whereas / unlike / both.</span></div><div class="command-row"><b>Calculate</b><span>Show the method, working, final value and correct unit.</span></div><div class="command-row"><b>Complete / Draw</b><span>Fill every required field or draw all required symbols, labels, arrows and branches.</span></div></section><section class="panel mark-examples"><h3>How to build a 2-mark explanation</h3><div class="mark-example-columns"><div><b>Weak answer</b><p>“Wi-Fi is easy.”</p><small>Too vague: no clear reason or context.</small></div><div><b>Stronger answer</b><p>“Wi-Fi lets students connect without an Ethernet cable, so they can move around the classroom while staying connected.”</p><small>Feature + reason/effect, linked to the situation.</small></div></div><p class="fine-print">This is a learning example, not a promise that every two-mark question uses the same allocation. The question-specific official mark scheme always takes priority.</p></section><section class="marking-disclaimer"><b>Important:</b> This guide explains recurring marking principles from the supplied Pearson mark schemes. It is not a replacement for the mark scheme for an individual paper. Different questions can have different accepted answers, mark caps and allocation rules. Check the exact session's official PDF before deciding a final mark.</section>`}
function materials(){const list=window.PAST_PAPERS||[];return `${heading('RESOURCE LIBRARY','Year 9 Learning Materials','Original Pearson Edexcel iLowerSecondary Computing source documents.')}<div class="grid two-col">${list.map(p=>`<article class="paper-card"><div class="card-kicker">YEAR 9 • ${esc(p.session).toUpperCase()}</div><h3>${esc(p.session)} Examination Set</h3><p>${esc(p.title)}</p><div class="card-actions"><a class="btn outline" href="resources/${encodeURIComponent(p.pdf)}" target="_blank">Question Paper ↗</a>${p.markSchemePdf?`<a class="btn outline" href="resources/${encodeURIComponent(p.markSchemePdf)}" target="_blank">Mark Scheme ↗</a>`:''}${p.examinerReportPdf?`<a class="btn outline" href="resources/${encodeURIComponent(p.examinerReportPdf)}" target="_blank">Examiner Report ↗</a>`:''}</div></article>`).join('')}</div><section class="panel" style="margin-top:17px"><b>Source and study note</b><p class="muted">The study notes are expanded explanations organised around the concepts visible in the supplied Year 9 papers. The original examination PDFs are preserved. The notes are teaching explanations, not official Pearson textbook pages or an official syllabus checklist.</p></section>`}
const paperQuestions=[
{id:1,marks:1,type:'text',q:'Complete the sentence: A ______ is used to take photographs while out with friends.',my:'ဝါကျကိုဖြည့်ပါ။ သူငယ်ချင်းများနှင့် အပြင်ထွက်စဉ် ဓာတ်ပုံရိုက်ရန် ______ ကို အသုံးပြုသည်။',accept:['smartphone'],answer:'Smartphone',why:'The mark scheme awards the mark for “A smartphone is used to take photographs while out with friends.”'},
{id:2,marks:2,type:'multi',q:'Select the TWO devices used in a home entertainment system.',my:'အိမ်တွင်းဖျော်ဖြေရေးစနစ်တွင် အသုံးပြုသော ကိရိယာနှစ်ခုကို ရွေးပါ။',opts:['Servo motor','Speakers','Television','Tilt sensor'],correct:['Speakers','Television'],answer:'Speakers and Television',why:'The 2025 mark scheme awards one mark for each correct tick: Speakers and Television.'},
{id:3,marks:2,type:'match',q:'Match each task to the correct type of software application.',my:'လုပ်ငန်းတစ်ခုစီကို သင့်တော်သော software application နှင့် တွဲပါ။',pairs:[['Costing of a school visit','Spreadsheet'],['Recording student information','Database']],answer:'Costing → Spreadsheet; Student records → Database',why:'Numerical costing is suited to a spreadsheet; structured student information is suited to a database.'},
{id:4,marks:1,type:'text',q:'Name one feature of an online shopping site that holds items a shopper has selected to buy.',my:'ဝယ်ယူရန်ရွေးထားသော ပစ္စည်းများကို သိမ်းထားပေးသည့် online shopping site ၏ feature တစ်ခုကို ဖော်ပြပါ။',accept:['basket','cart','bag'],answer:'Basket, cart or bag',why:'The mark scheme accepts Basket, Cart or Bag.'},
{id:5,marks:1,type:'mcq',q:'Which one of these is a benefit of shopping online?',my:'Online shopping ၏ အကျိုးကျေးဇူးတစ်ခုမှာ မည်သည်နည်း။',opts:['Can buy from local shops only','Can pay with cash','Can shop from home','Can try on clothes before buying'],correct:'Can shop from home',answer:'C — Can shop from home',why:'Online shopping allows customers to shop from home. The mark scheme identifies option C.'},
{id:6,marks:2,type:'text',q:'Describe what happens in a pharming attack.',my:'Pharming attack ဖြစ်ပွားသောအခါ ဘာဖြစ်သည်ကို ရှင်းပြပါ။',accept:['redirect','direct','fake website','fake app','legitimate looking'],answer:'A user is redirected to a fake website or app that looks legitimate.',why:'The mark scheme awards up to two linked marks: redirecting/directing a user, then to a fake or legitimate-looking website/app.',review:true},
{id:7,marks:1,type:'text',q:'Give one method, other than biometrics, that can be used to secure data and personal information online.',my:'Biometrics မဟုတ်ဘဲ online ပေါ်ရှိ ဒေတာနှင့် ကိုယ်ရေးအချက်အလက်ကို ကာကွယ်နိုင်သော နည်းလမ်းတစ်ခု ဖော်ပြပါ။',accept:['username','password','pin','passkey','single sign-on','sso','one-time passcode','otp'],answer:'Username, strong password, PIN, passkey, SSO or OTP',why:'These are accepted by the 2025 mark scheme. Biometric methods are not accepted for this question.'},
{id:8,marks:1,type:'mcq',q:'Which one of these is an example of appropriate digital etiquette?',my:'သင့်လျော်သော digital etiquette ဥပမာမှာ မည်သည်နည်း။',opts:['Helping a classmate pick up a pencil case','Playing a game on your smartphone during a lesson','Sending a nasty text message','Setting your smartphone to silent in the cinema'],correct:'Setting your smartphone to silent in the cinema',answer:'D — Setting your smartphone to silent in the cinema',why:'Digital etiquette is respectful behaviour when using technology. The mark scheme identifies D.'},
{id:9,marks:1,type:'mcq',q:'A classmate sends nasty online messages to a friend pretending to be you. What should you do?',my:'အတန်းဖော်တစ်ဦးက သင်ဟန်ဆောင်၍ သူငယ်ချင်းထံ မကောင်းသောစာများပို့လျှင် ဘာလုပ်သင့်သနည်း။',opts:['Do nothing and hope it stops','Report it to a teacher','Send nasty messages pretending to be them','Tell your friends about it'],correct:'Report it to a teacher',answer:'B — Report it to a teacher',why:'The mark scheme says cyberbullying should be reported to an appropriate adult or organisation, not ignored or retaliated against.'},
{id:10,marks:1,type:'mcq',q:'Which part of the body would be strained by using a monitor with poor contrast?',my:'Contrast မကောင်းသော monitor ကို အသုံးပြုခြင်းကြောင့် ကိုယ်ခန္ဓာ၏ မည်သည့်အစိတ်အပိုင်း ပင်ပန်းနိုင်သနည်း။',opts:['Eyes','Face','Neck','Wrists'],correct:'Eyes',answer:'A — Eyes',why:'The 2025 mark scheme identifies eyes as the part strained by poor monitor contrast.'},
{id:11,marks:2,type:'text',q:'Describe one difference between the Internet and the World Wide Web.',my:'Internet နှင့် World Wide Web တို့၏ ကွာခြားချက်တစ်ခုကို ရှင်းပြပါ။',accept:['network of networks','network of computers','hosted on the internet','collection of web pages','pages you see online','web pages'],answer:'The Internet is a global network of networks, whereas the WWW is a collection of webpages hosted on the Internet.',why:'For two marks, the answer must describe both: the Internet as a network of networks/computers and the WWW as webpages hosted on the Internet.',review:true},
{id:12,marks:1,type:'text',q:'State one purpose of copyright legislation.',my:'Copyright ဥပဒေ၏ ရည်ရွယ်ချက်တစ်ခုကို ဖော်ပြပါ။',accept:['protect the work','protect work','without permission','prevent people downloading','belongs to'],answer:'To protect an individual’s work and prevent unauthorised use.',why:'The mark scheme accepts protecting an individual’s work, preventing unauthorised use/adaptation or showing who owns the work.'},
{id:13,marks:1,type:'text',q:'State one way a teacher would use a virtual learning environment (VLE).',my:'ဆရာတစ်ဦးက Virtual Learning Environment (VLE) ကို အသုံးပြုနိုင်သည့် နည်းလမ်းတစ်ခုကို ဖော်ပြပါ။',accept:['upload','download','post resources','timetable','set online tests','feedback','mark pupil work','check progress','record marks'],answer:'Upload resources, set online tests, give feedback or check student progress.',why:'The mark scheme lists several valid uses, including uploading resources, setting tests, marking work and checking progress.'},
{id:14,marks:1,type:'mcq',q:'Which one of these is needed to find information using a search engine?',my:'Search engine ဖြင့် အချက်အလက်ရှာရန် မည်သည်လိုအပ်သနည်း။',opts:['Bookmark','Keyword','Sensor','Wiki'],correct:'Keyword',answer:'B — Keyword',why:'A keyword is a significant search term. A bookmark saves a URL; a sensor detects physical input; a wiki is collaborative.'},
{id:15,marks:1,type:'mcq',q:'Read the statement: “People with brown eyes are the most intelligent.” Which word correctly describes it?',my:'“မျက်လုံးအညိုရောင်ရှိသူများသည် ဉာဏ်အကောင်းဆုံးဖြစ်သည်” ဟူသောဖော်ပြချက်ကို မည်သို့သတ်မှတ်မည်နည်း။',opts:['Accurate','Current','Inaccurate','Reliable'],correct:'Inaccurate',answer:'C — Inaccurate',why:'The statement is unsupported and inaccurate. Eye colour does not determine intelligence.'},
{id:16,marks:2,type:'text',q:'Complete both parts: A blog displays the ______ entry first and can be used as an online ______.',my:'နှစ်နေရာဖြည့်ပါ။ Blog သည် ______ entry ကို အရင်ပြသပြီး online ______ အဖြစ် အသုံးပြုနိုင်သည်။',accept:['newest','diary'],answer:'Newest; diary',why:'The mark scheme awards one mark for “newest” and one for “diary”.',review:true},
{id:17,marks:1,type:'text',q:'Complete the sentence: An ______ is a set of instructions to complete a task.',my:'ဝါကျကိုဖြည့်ပါ။ လုပ်ငန်းတစ်ခု ပြီးမြောက်ရန် ညွှန်ကြားချက်များအစီအစဉ်ကို ______ ဟုခေါ်သည်။',accept:['algorithm'],answer:'Algorithm',why:'The mark scheme defines an algorithm as a set of instructions to complete a task.'},
{id:18,marks:1,type:'mcq',q:'Which one of these describes decomposition?',my:'Decomposition ကို ဖော်ပြသော အဖြေမှာ မည်သည်နည်း။',opts:['Breaking down a problem into smaller parts','Debugging errors in a problem','Finding the operators in a problem','Writing the structure of a problem'],correct:'Breaking down a problem into smaller parts',answer:'A — Breaking down a problem into smaller parts',why:'Decomposition means breaking a larger problem into smaller manageable parts.'},
{id:19,marks:2,type:'text',q:'A process checks whether a person is over 17. If they are, their age status changes to valid. Name the two missing actions: (1) after “Age more than 17?” and (2) the information displayed.',my:'အသက် ၁၇ နှစ်ကျော်/မကျော် စစ်ဆေးသည့် process ဖြစ်သည်။ ၁၇ နှစ်ကျော်ပါက age status ကို valid ပြောင်းသည်။ ပျောက်နေသော action နှစ်ခုကို ဖော်ပြပါ။',accept:['age status to valid','age status = valid','display name','name and age status'],answer:'(1) Change/set age status to valid. (2) Display the name and age status.',why:'One mark is awarded for setting age status to valid and one for displaying the name and age status.',review:true},
{id:20,marks:4,type:'multiText',q:'Choose the correct data type for each input: (a) Last name “Williams”; (b) Mark “50”; (c) Grade “A”; (d) Take test again? “True”.',my:'Input တစ်ခုစီအတွက် မှန်ကန်သော data type ကို ရွေးပါ။ (က) Last name “Williams”; (ခ) Mark “50”; (ဂ) Grade “A”; (ဃ) Take test again? “True”.',fields:['String','Integer','Char','Boolean'],answer:'String; Integer; Char; Boolean',why:'The official mark scheme gives String, Integer, Char and Boolean respectively.'}
];
function papers(){const list=window.PAST_PAPERS||[];const years=[...new Set(list.map(p=>p.year))].sort();const my=lang==='my';const first=years[0];return `${heading(my?'စာမေးပွဲဟောင်းများ':'EXAMINATION LIBRARY',my?'Year 9 စာမေးပွဲဟောင်းများ':'Year 9 Past Papers',my?'Pearson Edexcel iLowerSecondary Computing Year 9 မူရင်းစာမေးပွဲများကို နှစ်အလိုက်ကြည့်ရှုပါ။':'Pearson Edexcel iLowerSecondary Computing Year 9 original papers, mark schemes and examiner reports.')}<section class="panel paper-library">${panelHead(my?'နှစ်အလိုက် မေးခွန်းစာစောင်များ':'Question papers by year',my?'မူရင်း PDF ဖိုင်များ':'Original PDF source files')}<div class="year-tabs">${years.map(y=>`<button class="year-tab ${y===first?'selected':''}" data-year-filter="${y}">${y}</button>`).join('')}</div><div class="paper-list">${list.map(p=>`<article class="year-paper" data-paper-year="${p.year}" style="${p.year===first?'':'display:none'}"><div class="year-mark">${p.year}</div><div class="year-paper-info"><b>${esc(p.session)} — Year 9 Computing</b><small>${esc(p.title)} • 1 hour 20 minutes • 80 marks</small><small>${my?'မေးခွန်းစာစောင်၊ Mark Scheme နှင့် Examiner Report ကို သီးခြားဖွင့်နိုင်သည်။':'Open the question paper, official mark scheme and examiner report separately.'}</small></div><div class="toolbar-actions"><a class="btn outline" href="resources/${encodeURIComponent(p.pdf)}" target="_blank">${my?'Question Paper ကြည့်ရန်':'Question Paper'}</a>${p.markSchemePdf?`<a class="btn outline" href="resources/${encodeURIComponent(p.markSchemePdf)}" target="_blank">Mark Scheme</a>`:''}${p.examinerReportPdf?`<a class="btn outline" href="resources/${encodeURIComponent(p.examinerReportPdf)}" target="_blank">Examiner Report</a>`:''}</div></article>`).join('')}</div></section><section class="panel" style="margin-top:16px">${panelHead(my?'လေ့ကျင့်ဖြေဆိုခြင်း':'Digital practice status',my?'မူရင်း PDF များကို ထည့်သွင်းထားသည်':'Original source papers included')}<p class="muted">${my?'ဤဖိုင်တွင် မူရင်း PDF ၂၅ ဖိုင် ပါဝင်သည်။ PDF မေးခွန်းအားလုံးကို Interactive Question အဖြစ် မပြောင်းရသေးသဖြင့် ဤနေရာတွင် Digital Auto-marking ရရှိသည်ဟု မဆိုလိုပါ။':'This package contains 25 original PDFs. The paper questions have not all been converted into interactive answer fields, so these source PDFs are not presented as fully digital auto-marked exams.'}</p></section>`}
function openSourcePaper(id){const p=(window.PAST_PAPERS||[]).find(x=>x.id===id);if(!p)return;sourceAttempt={paper:p,answers:JSON.parse(localStorage.getItem('hjs_source_'+id)||'{}'),started:Date.now()};renderSourcePaper()}
function renderSourcePaper(){const p=sourceAttempt.paper,my=lang==='my';const rows=Array.from({length:p.questionCount},(_,i)=>{let n=i+1,hasKey=!!p.mcqKeys[String(n)],saved=sourceAttempt.answers[n]||'';return `<div class="source-answer-row"><label class="source-qno" for="ans-${n}">Q${n}</label><div>${hasKey?`<select id="ans-${n}" data-source-answer="${n}" class="field"><option value="">${my?'အဖြေရွေးပါ':'Choose an answer'}</option>${['A','B','C','D'].map(x=>`<option value="${x}" ${saved.toUpperCase()===x?'selected':''}>${x}</option>`).join('')}</select>`:`<textarea id="ans-${n}" data-source-answer="${n}" rows="2" placeholder="${my?'မေးခွန်း '+n+' အတွက် အဖြေရေးပါ':'Write your answer for Question '+n}">${esc(saved)}</textarea>`}<small class="save-state" id="saved-${n}">${saved?(my?'သိမ်းပြီး ✓':'Saved ✓'):(my?'မဖြေရသေးပါ':'Not answered')}</small></div></div>`}).join('');$('#content').innerHTML=`${heading(my?'ဒစ်ဂျစ်တယ် မေးခွန်းစာစောင်':'DIGITAL PAST PAPER',`${p.year} • ${esc(p.session)}`,my?'ဘယ်ဘက်တွင် မူရင်းမေးခွန်းစာရွက်ကိုကြည့်ပြီး ညာဘက် Answer Sheet တွင် ဖြေဆိုပါ။':'View the original question paper and enter your answers in the digital answer sheet.','<button class="btn outline" id="backPaperLibrary">← '+(my?'မေးခွန်းစာစောင်များ':'All papers')+'</button>')}<div class="source-paper-toolbar"><div><b>${esc(p.title)}</b><small>${p.duration} ${my?'မိနစ်':'minutes'} • ${p.totalMarks} ${my?'မှတ်':'marks'} • ${p.questionCount} ${my?'မေးခွန်း':'questions'}</small></div><div class="toolbar-actions"><a class="btn outline" href="resources/${encodeURIComponent(p.pdf)}" target="_blank">${my?'PDF ဖွင့်ရန်':'Open PDF'} ↗</a>${p.markSchemePdf?`<a class="btn outline" href="resources/${encodeURIComponent(p.markSchemePdf)}" target="_blank">${my?'အဖြေလွှာ (Mark Scheme)':'Mark Scheme'} ↗</a>`:''}</div></div><div class="source-paper-layout"><section class="source-pdf"><div class="source-pdf-head"><b>${my?'မူရင်းမေးခွန်းစာရွက်':'Original question paper'} • ${p.year}</b><a href="resources/${encodeURIComponent(p.pdf)}" target="_blank">${my?'PDF အသစ်ဖွင့်ရန်':'Open PDF'} ↗</a></div><iframe title="Original question paper" src="resources/${encodeURIComponent(p.pdf)}#toolbar=1&navpanes=0&view=FitH"></iframe></section><section class="source-answers"><div class="answer-panel-head"><h2>${my?'ဒစ်ဂျစ်တယ် အဖြေလွှာ':'Digital answer sheet'}</h2><p>${my?'မေးခွန်းတစ်ခုချင်းစီအတွက် အဖြေထည့်ပါ။ အလိုအလျောက် သိမ်းဆည်းပေးပါမည်။':'Enter an answer for each question. Your answers are saved automatically.'}</p></div><div class="answer-question-list">${rows}</div><div class="source-submit"><button class="btn gold-btn full" id="submitSourcePaper">${my?'တင်သွင်းပြီး ရလဒ်ကြည့်ရန်':'Submit & show result'}</button><small>${my?'Official answer key ရှိသော မေးခွန်းများကို Auto-check လုပ်ပြီး ကျန်မေးခွန်းများကို ဆရာ/ဆရာမ စစ်ဆေးရန် ပြပါမည်။':'Questions with verified answer keys are auto-checked. Other responses are flagged for teacher review.'}</small></div></section></div>`;
$('#backPaperLibrary').onclick=()=>{sourceAttempt=null;go('papers')};$$('[data-source-answer]').forEach(el=>el.addEventListener('input',()=>{let n=el.dataset.sourceAnswer;sourceAttempt.answers[n]=el.value;localStorage.setItem('hjs_source_'+p.id,JSON.stringify(sourceAttempt.answers));$('#saved-'+n).textContent=my?'သိမ်းပြီး ✓':'Saved ✓'}));$('#submitSourcePaper').onclick=()=>{if(confirm(my?'အဖြေလွှာကို တင်သွင်းပြီး ရလဒ်ကြည့်မလား။':'Submit this answer sheet and show your result?'))submitSourcePaper()}}

function submitSourcePaper(){const p=sourceAttempt.paper;let autoScore=0,autoCount=0,pending=0,answered=0,wrong=0,unanswered=0,review=[];for(let n=1;n<=p.questionCount;n++){let a=(sourceAttempt.answers[n]||'').trim();if(a)answered++;else unanswered++;let key=p.mcqKeys[String(n)];if(key){autoCount++;let ok=a.toUpperCase().trim()===key.answer;if(ok)autoScore++;else if(a)wrong++;review.push({n,answer:a||'—',expected:key.answer,correct:ok,type:'auto',mark:ok?1:0,max:1})}else{pending++;review.push({n,answer:a||'—',expected:(p.markingGuide&&p.markingGuide[String(n)])||'No official marking guidance was supplied for this question.',correct:null,type:'manual',mark:null,max:null})}}let percent=autoCount?Math.round(autoScore/autoCount*100):0;let result={id:'source-'+Date.now(),sourcePaper:true,title:p.title,pdf:p.pdf,markSchemePdf:p.markSchemePdf,date:new Date().toISOString(),autoScore,autoCount,score:autoScore,max:autoCount,percent,pending,answered,wrong,unanswered,questionCount:p.questionCount,review};state.results.unshift(result);save();localStorage.removeItem('hjs_source_'+p.id);sourceAttempt=null;renderSourceResult(result)}

function renderSourceResult(r){currentPage='papers';$('#crumb').textContent=lang==='my'?'ရလဒ်':'Results';let my=lang==='my';const correct=r.autoScore||0,wrong=r.wrong||0,checked=r.autoCount||0,percent=r.percent||0;$('#content').innerHTML=`${heading(my?'အဖြေလွှာ တင်သွင်းပြီးပါပြီ':'PAPER SUBMITTED',my?'ဖြေဆိုမှုရလဒ်':'Your examination result',my?'အဖြေမှန်/မှားနှင့် ရမှတ်များကို အောက်တွင်ကြည့်နိုင်ပါသည်။':'Your correct answers, incorrect answers and marks are shown below.')}<p><a class="text-link" href="resources/${encodeURIComponent(r.pdf||'')}" target="_blank">${my?'မူရင်းမေးခွန်းကြည့်ရန်':'View question paper'} ↗</a> ${r.markSchemePdf?`<a class="text-link" style="margin-left:14px" href="resources/${encodeURIComponent(r.markSchemePdf)}" target="_blank">${my?'Mark Scheme ဖွင့်ရန်':'Open official mark scheme'} ↗</a>`:''}</p><section class="panel"><div class="grid stats-grid"><div class="stat-card"><div class="stat-top">${my?'ရမှတ်':'Score'}</div><div class="stat-value">${correct} / ${checked}</div><div class="stat-foot">${my?'စစ်ဆေးနိုင်သောမေးခွန်းများအနက်':'Of verified questions'}</div></div><div class="stat-card"><div class="stat-top">${my?'ရာခိုင်နှုန်း':'Percentage'}</div><div class="stat-value">${percent}%</div><div class="stat-foot">${my?'အလိုအလျောက်စစ်ဆေးထားသောအပိုင်း':'Auto-marked section only'}</div></div><div class="stat-card"><div class="stat-top">${my?'အဖြေမှန်':'Correct'}</div><div class="stat-value">${correct}</div></div><div class="stat-card"><div class="stat-top">${my?'အဖြေမှား':'Incorrect'}</div><div class="stat-value">${wrong}</div></div></div><div class="progress-line" style="margin-top:14px"><span style="width:${percent}%"></span></div><p class="muted" style="margin-top:12px">${my?'ဖြေဆိုထားသည်':'Answered'} ${r.answered} / ${r.questionCount} • ${my?'မဖြေရသေး':'Unanswered'} ${r.unanswered||0} • ${my?'ရေးသားဖြေဆိုမှု / Key မရှိသောမေးခွန်း':'Written-response / unkeyed questions'} ${r.pending}. ${my?'ဤရမှတ်သည် အဖြေလွှာ Key အတည်ပြုထားသော မေးခွန်းများအတွက်သာ ဖြစ်ပါသည်။':'This score includes only questions with a verified objective answer key. Written responses are shown with the official marking guidance but are not automatically awarded partial marks.'}</p></section><section class="panel">${panelHead(my?'မေးခွန်းအလိုက် အဖြေစစ်ဆေးချက်':'Question-by-question marking',my?'အစိမ်း = မှန်၊ အနီ = မှား၊ အဝါ = စစ်ဆေးရန်':'Green = correct, red = incorrect, amber = review')}${r.review.map(x=>`<div class="review-item ${x.correct===true?'correct':x.correct===false?'wrong':''}"><h4>${my?'မေးခွန်း':'Question'} ${x.n} <span class="pill ${x.correct===true?'green':x.correct===false?'gold':''}">${x.type==='auto'?(x.correct?(my?'မှန် ✓':'Correct ✓'):(my?'မှား ✗':'Incorrect ✗')):(my?'Mark Scheme ကိုကြည့်ရန်':'Mark scheme guidance')}</span>${x.type==='auto'?`<span class="right">${x.mark} / ${x.max} ${my?'မှတ်':'mark'}</span>`:''}</h4><p><b>${my?'သင့်အဖြေ':'Your answer'}:</b> ${esc(x.answer)}</p><p><b>${x.type==='auto'?(my?'အဖြေလွှာအရ အဖြေမှန်':'Answer-sheet key'):(my?'တရားဝင် Mark Scheme / အဖြေသတ်မှတ်ချက်':'Official mark scheme / accepted answer guidance')}:</b> ${esc(x.expected)}</p></div>`).join('')}</section><button class="btn primary" data-page="papers">${my?'မေးခွန်းစာစောင်များသို့ ပြန်သွားရန်':'Back to past papers'}</button>`}
function practice(){return `${heading('EXAM PREPARATION','Year 9 Computing Revision','Revise the concepts tested in the supplied iLowerSecondary papers.')}<div class="grid three-col"><article class="feature-card"><div class="card-kicker">TOPIC REVISION</div><h3>Study Notes</h3><p>Eight detailed topics with worked examples, bilingual explanations, diagrams, flowcharts and visual guides.</p><button class="btn primary" data-page="notes">Open Study Notes →</button></article><article class="feature-card"><div class="card-kicker">PAST PAPER PRACTICE</div><h3>Original Papers</h3><p>Open the Pearson Edexcel Year 9 question papers and answer them on paper or in your own document.</p><button class="btn outline" data-page="papers">Browse Past Papers →</button></article><article class="feature-card"><div class="card-kicker">LEARNING REVIEW</div><h3>Progress Tracker</h3><p>Mark topics as complete and revisit any areas that need more study.</p><button class="btn outline" data-page="progress">View Progress →</button></article></div><section class="panel" style="margin-top:17px">${panelHead('Exam format in the supplied papers','Pearson Edexcel LCP11/01')}<p class="muted">The supplied Year 9 papers state a duration of 1 hour 20 minutes and a total of 80 marks. Read the front-page instructions for each session because the number and style of questions may vary.</p></section>`}
function practical(){return `${heading('LEARN BY DOING','ICT Practical Skills','Follow each task, then use the self-check checklist to evaluate your work.')}<div class="grid three-col">${D.practical.map((p,i)=>`<article class="feature-card"><div class="card-kicker">PRACTICAL 0${i+1} • ${p.level.toUpperCase()}</div><h3>${p.title}</h3><p>${p.objective}</p><button class="btn outline" data-practical="${i}">Open practical →</button></article>`).join('')}</div>`}
function results(){return `${heading('ASSESSMENT HISTORY','My Results','Review your submitted examinations and feedback.')}<section class="panel">${panelHead('All attempts',`${state.results.length} saved`)}${state.results.length?state.results.map(r=>`<div class="list-row"><div class="list-icon">▥</div><div><b>${esc(r.title)}</b><small>${new Date(r.date).toLocaleString()} • ${r.score}/${r.max} marks</small></div><span class="right">${r.percent}%</span><button class="text-link" data-review="${r.id}">Review →</button></div>`).join(''):'<div class="empty">Your exam history is empty. Submit an attempt to see your results here.</div>'}</section>`}
function progress(){let avg=state.results.length?Math.round(state.results.reduce((a,r)=>a+r.percent,0)/state.results.length):0;return `${heading('PERFORMANCE INSIGHTS','Progress Report','A snapshot of your activity saved in this browser.')}<div class="grid stats-grid"><div class="stat-card"><div class="stat-top">Topics completed</div><div class="stat-value">${state.completed.length}/${D.notes.length}</div></div><div class="stat-card"><div class="stat-top">Average score</div><div class="stat-value">${avg}%</div></div><div class="stat-card"><div class="stat-top">Attempts</div><div class="stat-value">${state.results.length}</div></div><div class="stat-card"><div class="stat-top">Notes opened</div><div class="stat-value">${state.notesSeen.length}</div></div></div><section class="panel">${panelHead('Topic completion','Mark topics complete from the Study Notes page')}${D.notes.map(n=>`<div class="list-row"><div class="list-icon">${state.completed.includes(n.id)?'✓':'▧'}</div><div style="flex:1"><b>${n.title}</b><small>${state.completed.includes(n.id)?'Completed':'Not yet completed'}</small></div><span class="pill ${state.completed.includes(n.id)?'green':''}">${state.completed.includes(n.id)?'Done':'To do'}</span></div>`).join('')}</section>`}
function profile(){return `${heading('YOUR ACCOUNT','Student Profile','Your local learner profile.')}<section class="panel" style="max-width:620px"><div class="course-progress"><div class="avatar" style="width:60px;height:60px;font-size:23px">${esc(state.user.name[0].toUpperCase())}</div><div><h2 style="font:700 22px 'Playfair Display';margin:0">${esc(state.user.name)}</h2><p class="muted" style="margin:4px 0">Year 9 Computing Student • House of J&S</p></div></div><hr style="border:0;border-top:1px solid var(--line);margin:20px 0"><p><b>Course</b><br><span class="muted">Pearson Edexcel International Award in Lower Secondary Computing (LCP11/01)</span></p><p><b>Account mode</b><br><span class="muted">Local demonstration account</span></p><p class="muted">This prototype stores progress in this browser only. For multi-device accounts, secure authentication and shared records, connect the supplied Supabase backend schema.</p></section>`}
function teacher(){return `${heading('CENTRE MANAGEMENT','Teacher Dashboard','Demo teacher workspace. Secure teacher authentication must be configured before public deployment.')}<section class="panel"><div class="eyebrow2">DEMO ADMINISTRATION</div><h2 style="font:700 22px 'Playfair Display';color:var(--navy)">Manage learning and assessment</h2><p class="muted">The current offline build includes a teacher workspace preview and a question authoring form. It does not yet provide secure multi-user teacher permissions; connect Supabase and enable the included Row Level Security policies before using real student data.</p><div class="grid two-col"><div class="feature-card"><h3>Question bank</h3><p>Create a local draft question for the teacher to review.</p><button class="btn outline" id="addQuestion">Create question draft</button></div><div class="feature-card"><h3>Student performance</h3><p>${state.results.length} local attempts have been recorded in this browser.</p><button class="btn outline" data-page="results">View attempts</button></div></div></section><section class="panel">${panelHead('Recent learner attempts','Local demo data')}${state.results.length?state.results.map(r=>`<div class="list-row"><div><b>${esc(state.user.name)} — ${esc(r.title)}</b><small>${new Date(r.date).toLocaleString()}</small></div><span class="right">${r.percent}%</span></div>`).join(''):'<div class="empty">No learner attempts available.</div>'}</section>`}
function settings(){return `${heading('PREFERENCES','Settings','Adjust your learning portal preferences.')}<section class="panel" style="max-width:650px">${panelHead('Language','Interface and study note display')}<div class="list-row"><div><b>Current language</b><small>Switch between English and Myanmar from the top bar.</small></div><button class="btn outline" id="toggleLang">${lang==='en'?'မြန်မာ':'English'}</button></div><div class="list-row"><div><b>Clear local learning data</b><small>Remove saved progress and attempt history from this browser.</small></div><button class="btn outline" id="clearData">Clear data</button></div><p class="muted">Do not use this local prototype to store sensitive personal information. Configure server-side authentication and database policies before production use.</p></section>`}
function render(){if(!state.user)return;let html=({dashboard,overview,notes,marking,materials,papers,practice,practical,results,progress,profile,teacher,settings})[currentPage]();$('#content').innerHTML=html;wireDynamic();if(currentPage==='notes'){state.notesSeen=[...new Set([...state.notesSeen,noteId])];save()}}
function wireDynamic(){ $$('[data-open-source-paper]').forEach(b=>b.onclick=()=>openSourcePaper(b.dataset.openSourcePaper));$$('[data-year-filter]').forEach(b=>b.onclick=()=>{$$('[data-year-filter]').forEach(x=>x.classList.toggle('selected',x===b));$$('[data-paper-year]').forEach(x=>x.style.display=(x.dataset.paperYear===b.dataset.yearFilter?'flex':'none'))}); $$('[data-note]').forEach(b=>b.onclick=()=>{noteId=b.dataset.note;render()});$$('[data-open-note]').forEach(b=>b.onclick=()=>{noteId=b.dataset.openNote;go('notes')});$$('[data-complete]').forEach(b=>b.onclick=()=>{let id=b.dataset.complete;state.completed=[...new Set([...state.completed,id])];save();render()});$$('[data-start-paper]').forEach(b=>b.onclick=()=>startExam());$$('[data-open-source-paper]').forEach(b=>b.onclick=()=>openSourcePaper(b.dataset.openSourcePaper));$$('[data-practical]').forEach(b=>b.onclick=()=>openPractical(+b.dataset.practical));$$('[data-review]').forEach(b=>b.onclick=()=>reviewResult(b.dataset.review));$('#toggleLang')?.addEventListener('click',()=>$('#langBtn').click());$('#clearData')?.addEventListener('click',()=>{if(confirm('Delete all saved progress and exam history from this browser?')){state.completed=[];state.results=[];state.notesSeen=[];save();render()}});$('#addQuestion')?.addEventListener('click',addQuestion)}
function startExam(){if(exam)return;exam={id:'attempt-'+Date.now(),title:'Year 9 Computing Practice Test',questions:paperQuestions.map(q=>({...q})),answers:{},index:0,start:Date.now(),duration:60*60,practice:practiceMode};renderExam();timerHandle=setInterval(tick,1000)}
function tick(){if(!exam)return;let left=Math.max(0,exam.duration-Math.floor((Date.now()-exam.start)/1000));let t=$('#timer');if(t)t.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(left===0)submitExam(true)}
function answerVal(q){return exam.answers[q.id]}
function renderExam(){let q=exam.questions[exam.index],ans=answerVal(q);$('#content').innerHTML=`<div class="page-heading"><div><div class="eyebrow2">EXAMINATION IN PROGRESS</div><h1>Year 9 Computing Practice Test</h1><p>Answer each question and review your progress before submitting.</p></div><button class="btn outline" id="exitExam">Exit attempt</button></div><section class="exam-shell"><div class="exam-head"><div><h2>Pearson Edexcel • LCP11/01</h2><small>Year 9 Computing • ${exam.questions.length} digitised questions • Original paper duration: 1 hour 20 minutes</small></div><div class="timer" id="timer">60:00</div></div><div class="exam-body"><div class="question-area"><div class="question-meta"><span>QUESTION ${q.id} OF ${exam.questions.length}</span><span class="pill gold">${q.marks} ${q.marks===1?'MARK':'MARKS'}</span><span class="pill">${q.type==='mcq'||q.type==='multi'?'OBJECTIVE':'WRITTEN'}</span></div><h3>${esc(lang==='en'?q.q:q.my)}</h3>${renderQuestionInput(q,ans)}<div style="margin-top:18px;font-size:10px;color:#9aa0aa">Your answer is saved automatically in this attempt while the page remains open.</div></div><aside class="exam-side"><h4>QUESTION NAVIGATION</h4><div class="q-grid">${exam.questions.map((x,i)=>`<button class="q-num ${exam.index===i?'current':''} ${hasAnswer(x)?'done':''}" data-qindex="${i}">${x.id}</button>`).join('')}</div><small><span style="color:#9a772e">■</span> Answered &nbsp; <span style="color:#172238">■</span> Current<br>Answered ${exam.questions.filter(hasAnswer).length} of ${exam.questions.length}<br><br>Objective questions are auto-marked. Some written answers may require teacher review.</small></aside></div><div class="exam-controls"><button class="btn outline" id="prevQ" ${exam.index===0?'disabled':''}>← Previous</button><span style="font-size:10px;color:#939aa5">Question ${exam.index+1} / ${exam.questions.length}</span>${exam.index===exam.questions.length-1?'<button class="btn gold-btn" id="submitExam">Submit examination</button>':'<button class="btn primary" id="nextQ">Next question →</button>'}</div></section>`;
$$('[data-qindex]').forEach(b=>b.onclick=()=>{exam.index=+b.dataset.qindex;renderExam()});$('#prevQ')?.addEventListener('click',()=>{exam.index--;renderExam()});$('#nextQ')?.addEventListener('click',()=>{exam.index++;renderExam()});$('#submitExam')?.addEventListener('click',()=>confirmSubmit());$('#exitExam')?.addEventListener('click',()=>{if(confirm('Exit this attempt? Your answers will not be submitted.')){clearInterval(timerHandle);exam=null;go('papers')}});
$$('[data-answer]').forEach(el=>el.addEventListener('change',()=>{let q=exam.questions[exam.index],key=el.dataset.answer;if(q.type==='multi'){let v=[...$$('[data-answer="multi"]:checked')].map(x=>x.value);exam.answers[q.id]=v}else if(q.type==='multiText'){let v={...(exam.answers[q.id]||{})};v[key]=el.value;exam.answers[q.id]=v}else if(q.type==='match'){let v={...(exam.answers[q.id]||{})};v[key]=el.value;exam.answers[q.id]=v}else exam.answers[q.id]=el.value;renderExamKeepFocus()}));$$('[data-answer]').filter(x=>x.tagName==='TEXTAREA'||x.tagName==='INPUT').forEach(el=>el.addEventListener('input',()=>{let q=exam.questions[exam.index],key=el.dataset.answer;if(q.type==='multiText'){let v={...(exam.answers[q.id]||{})};v[key]=el.value;exam.answers[q.id]=v}else exam.answers[q.id]=el.value;let count=$('.exam-side small');if(count)count.innerHTML=`<span style="color:#9a772e">■</span> Answered &nbsp; <span style="color:#172238">■</span> Current<br>Answered ${exam.questions.filter(hasAnswer).length} of ${exam.questions.length}<br><br>Objective questions are auto-marked. Some written answers may require teacher review.`}));tick()}
function renderQuestionInput(q,ans){if(q.type==='mcq')return q.opts.map((o,i)=>`<label class="option"><input type="radio" name="q${q.id}" data-answer="single" value="${esc(o)}" ${ans===o?'checked':''}><span><b>${'ABCD'[i]}.</b> ${esc(o)}</span></label>`).join('');if(q.type==='multi')return `<p class="muted">Select two answers.</p>`+q.opts.map(o=>`<label class="option"><input type="checkbox" data-answer="multi" value="${esc(o)}" ${(ans||[]).includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('');if(q.type==='match')return q.pairs.map((p,i)=>`<div class="task-step"><b>${esc(p[0])}</b><select class="field" data-answer="${i}" style="margin-left:12px;padding:8px"><option value="">Choose application</option>${['Database','Graphics','Presentation','Spreadsheet','Word processing'].map(o=>`<option ${ans?.[i]===o?'selected':''}>${o}</option>`).join('')}</select></div>`).join('');if(q.type==='multiText')return q.fields.map((f,i)=>`<label style="display:block;font-size:11px;font-weight:700;margin:13px 0 5px">(${String.fromCharCode(97+i)}) ${f}</label><input class="field" style="width:100%" data-answer="${i}" value="${esc(ans?.[i]||'')}" placeholder="Enter data type">`).join('');return `<textarea class="answer-input" data-answer="single" placeholder="Type your answer here...">${esc(ans||'')}</textarea>`}
function renderExamKeepFocus(){let q=exam.questions[exam.index],a=exam.answers[q.id];let status=$('.exam-side small');if(status)status.innerHTML=`<span style="color:#9a772e">■</span> Answered &nbsp; <span style="color:#172238">■</span> Current<br>Answered ${exam.questions.filter(hasAnswer).length} of ${exam.questions.length}<br><br>Objective questions are auto-marked. Some written answers may require teacher review.`}
function hasAnswer(q){let a=exam.answers[q.id];if(Array.isArray(a))return a.length>0;if(a&&typeof a==='object')return Object.values(a).some(Boolean);return !!String(a||'').trim()}
function confirmSubmit(){let unanswered=exam.questions.filter(q=>!hasAnswer(q)).length;modal('Submit your examination?',`You have ${unanswered} unanswered question(s). Once submitted, you cannot change your answers in this attempt.`,()=>submitExam(false))}
function norm(s){return String(s||'').toLowerCase().replace(/[^a-z0-9 ]/g,' ').replace(/\s+/g,' ').trim()}
function markQuestion(q,a){let score=0,feedback='',correct=false,manual=false;if(q.type==='mcq'){correct=a===q.correct;score=correct?q.marks:0}else if(q.type==='multi'){let expected=q.correct,got=a||[];score=got.filter(x=>expected.includes(x)).length===2&&got.length===2?2:0;correct=score===q.marks}else if(q.type==='match'){let pairs=q.pairs;score=pairs.reduce((s,p,i)=>s+((a||{})[i]===p[1]?1:0),0);correct=score===q.marks}else if(q.type==='multiText'){let expected=['string','integer','char','boolean'];score=expected.reduce((s,x,i)=>s+(norm(a?.[i])===x?1:0),0);correct=score===q.marks}else{let text=norm(a);let hits=q.accept.filter(k=>text.includes(norm(k)));if(q.id===6){score=hits.some(x=>['redirect','direct'].includes(x))&&hits.some(x=>['fake website','fake app','legitimate looking'].includes(x))?2:hits.length?1:0}else if(q.id===11){let internet=hits.some(x=>['network of networks','network of computers'].includes(x));let web=hits.some(x=>['hosted on the internet','collection of web pages','pages you see online','web pages'].includes(x));score=(internet?1:0)+(web?1:0)}else if(q.id===16){score=(hits.includes('newest')?1:0)+(hits.includes('diary')?1:0)}else if(q.id===19){score=(hits.some(x=>['age status to valid','age status = valid'].includes(x))?1:0)+(hits.some(x=>['display name','name and age status'].includes(x))?1:0)}else score=hits.length?Math.min(q.marks,1):0;correct=score===q.marks;manual=!!q.review&&!correct}
return {score,correct,manual,feedback:manual?'Provisional keyword check — teacher review recommended.':correct?'Correct.': 'Not matched to the accepted answer phrases. Review the explanation.',answer:q.answer,student:formatAnswer(q,a)}}
function formatAnswer(q,a){if(!hasAnswer(q))return 'Unanswered';if(Array.isArray(a))return a.join(', ');if(a&&typeof a==='object')return Object.entries(a).map(([k,v])=>`${q.type==='multiText'?`(${String.fromCharCode(97,+k)})`:''} ${v}`).join('; ');return a}
function submitExam(auto){if(!exam)return;clearInterval(timerHandle);let details=exam.questions.map(q=>({q,mark:markQuestion(q,exam.answers[q.id])})),score=details.reduce((s,d)=>s+d.mark.score,0),max=details.reduce((s,d)=>s+d.q.marks,0),result={id:exam.id,title:exam.title,date:new Date().toISOString(),score,max,percent:Math.round(score/max*100),details,answers:exam.answers,auto};state.results.unshift(result);save();exam=null;renderResult(result)}
function renderResult(r){currentPage='results';$('#crumb').textContent='Exam Results';let correct=r.details.filter(d=>d.mark.correct).length,wrong=r.details.filter(d=>hasSavedAnswer(d)&&!d.mark.correct).length,unanswered=r.details.length-correct-wrong,review=r.details.filter(d=>d.mark.manual).length;$('#content').innerHTML=`${heading('ASSESSMENT COMPLETE','Your examination result','Review your answers and use the feedback to guide your next revision.')}<section class="panel"><div class="result-score"><div class="score-big">${r.percent}%</div><div><div class="eyebrow2">MARKS OBTAINED</div><h2 style="font:700 22px 'Playfair Display';margin:3px 0;color:var(--navy)">${r.score} / ${r.max}</h2><span class="pill ${r.percent>=50?'green':'gold'}">${r.percent>=50?'Pass indicator (50%+)':'More practice recommended'}</span><p style="font-size:10px;color:var(--muted)">${r.title}</p></div></div><div class="grid three-col" style="margin-top:18px"><div><b>${correct}</b><p class="muted">Fully correct</p></div><div><b>${wrong}</b><p class="muted">Incorrect / partial</p></div><div><b>${unanswered}</b><p class="muted">Unanswered</p></div></div><p class="muted">${review} written response(s) may need teacher review. This result is an automated learning aid, not an official Pearson grade.</p></section><section class="panel">${panelHead('Answer-by-answer review','Correct answers and explanations')}${r.details.map(d=>`<article class="review-item ${d.mark.correct?'correct':'wrong'}"><h4>Q${d.q.id}. ${esc(d.q.q)} <span class="pill">${d.mark.score}/${d.q.marks}</span></h4><p><b>Your answer:</b> ${esc(formatAnswer(d.q,r.answers[d.q.id]))}</p><p><b>Expected answer:</b> ${esc(d.mark.answer)}</p><div class="feedback ${d.mark.correct?'good':'bad'}">${esc(d.mark.feedback)}<br><b>Explanation:</b> ${esc(d.q.why)}</div></article>`).join('')}</section><button class="btn primary" data-page="papers">Back to past papers</button>`}
function hasSavedAnswer(d){let a=d.mark.student;return a!=='Unanswered'}
function reviewResult(id){let r=state.results.find(x=>x.id===id);if(r)renderResult(r)}
function modal(title,body,onYes){let root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><h3>${title}</h3><p>${body}</p><div class="modal-actions"><button class="btn outline" id="modalNo">Cancel</button><button class="btn primary" id="modalYes">Confirm</button></div></div></div>`;$('#modalNo').onclick=()=>root.innerHTML='';$('#modalYes').onclick=()=>{root.innerHTML='';onYes()}}
function openPractical(i){let p=D.practical[i],root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal" style="max-width:600px;max-height:90vh;overflow:auto"><div class="card-kicker">PRACTICAL SKILLS • ${p.level.toUpperCase()}</div><h3>${p.title}</h3><p><b>Objective:</b> ${p.objective}</p><h4>Step-by-step instructions</h4>${p.steps.map((s,i)=>`<div class="task-step">${i+1}. ${s}</div>`).join('')}<h4>Self-check</h4>${p.checks.map((s,i)=>`<label class="task-step" style="display:block"><input type="checkbox" data-check="${i}">${s}</label>`).join('')}<div class="note-callout"><b>Expected result:</b> ${p.result}</div><div class="modal-actions"><button class="btn outline" id="closePractical">Close</button><button class="btn gold-btn" id="savePractical">Save completion</button></div></div></div>`;$('#closePractical').onclick=()=>root.innerHTML='';$('#savePractical').onclick=()=>{let all=$$('[data-check]').every(x=>x.checked);if(!all){alert('Please complete each self-check item before saving.');return}state.completed=[...new Set([...state.completed,`practical-${i}`])];save();root.innerHTML='';alert('Practical self-check saved on this device.')}}
function addQuestion(){let root=$('#modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><h3>Create question draft</h3><p>Drafts are local to this browser and are not published to students.</p><label>Question text</label><textarea id="draftQ" class="answer-input" placeholder="Write the question..."></textarea><label style="display:block;margin:12px 0 5px">Teacher answer / marking notes</label><textarea id="draftA" class="answer-input" placeholder="Enter expected answer and marks..."></textarea><div class="modal-actions"><button class="btn outline" id="cancelDraft">Cancel</button><button class="btn primary" id="saveDraft">Save draft</button></div></div></div>`;$('#cancelDraft').onclick=()=>root.innerHTML='';$('#saveDraft').onclick=()=>{let drafts=JSON.parse(localStorage.getItem('hjs_question_drafts')||'[]');drafts.push({q:$('#draftQ').value,a:$('#draftA').value,date:new Date().toISOString()});localStorage.setItem('hjs_question_drafts',JSON.stringify(drafts));root.innerHTML='';alert('Question draft saved locally.')}}
if(state.user){$('#loginScreen').classList.add('hidden');$('#app').classList.remove('hidden');$('#topName').textContent=state.user.name;$('#avatar').textContent=state.user.name[0].toUpperCase();render()}else $('#app').classList.add('hidden');
})();
